<script setup lang="ts">
import AccountingCurrencyFields from './AccountingCurrencyFields.vue';
import {needsApproval,approvalTypes} from './approvalPolicy';
import {useAccountingPermissions} from './permissions';
const can=useAccountingPermissions();
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import AccountingApprovalPanel from './AccountingApprovalPanel.vue';
import AccountingSelect from './AccountingSelect.vue';
import AccountingDocument from './AccountingDocument.vue';
import AdminDialog from '../../AdminDialog.vue';
import {requestKey} from './requestKey';
const props=defineProps<{kind:'cash_receipt'|'cash_payment';company:number;book:any;accounts:any[];canManage:boolean;canAdmin:boolean;csrf?:string}>();
const emit=defineEmits(['notice','changed','setup','single']);
const requiresApproval=computed(()=>needsApproval(props.book,props.kind));
const receipt=computed(()=>props.kind==='cash_receipt'),title=computed(()=>receipt.value?'Cash receipt vouchers':'Cash payment vouchers');
const today=new Date().toLocaleDateString('en-CA'),data=ref<any>(null),editor=ref<any>(null),page=ref(1),status=ref(''),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),confirm=ref(''),reason=ref(''),reverseDate=ref(today);
const cash=computed(()=>props.accounts.filter(a=>a.active&&!a.is_group&&a.root_type==='Asset'&&a.account_type==='Cash'));
const quickEntry=ref(false);
const quickRoot=computed(()=>receipt.value?'Income':'Expense');
const offsets=computed(()=>props.accounts.filter(a=>a.active&&!a.is_group&&(!quickEntry.value||a.root_type===quickRoot.value)&&!['Cash','Bank','Receivable','Payable'].includes(a.account_type)));
const savedSignature=ref('');
function signature(e:any){return JSON.stringify([e.currency,e.exchange_rate,e.posting_date,e.voucher_person,e.reference||'',e.remarks||'',e.cash_id,e.offset_id,String(e.amount)]);}
function review(){formError.value='';if(signature(editor.value)!==savedSignature.value){formError.value='Save the draft changes before reviewing posting.';return;}confirm.value='post';}
const draft=computed(()=>editor.value?.status==='draft');
const group=computed(()=>receipt.value?'cash_receipts':'cash_payments');
const pending=computed(()=>editor.value?.approval&&!['returned','withdrawn'].includes(editor.value.approval.stage));
const mayEdit=computed(()=>!pending.value&&can(group.value+(editor.value?.id?'.update':'.create')));
const money=(v:any)=>Number(v||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
async function api(path:string,body?:any){const response=await fetch('/accounting/api/'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to complete this action.');return result;}
let generation=0;onBeforeUnmount(()=>generation++);
async function load(){const gen=++generation;loading.value=true;error.value='';try{const result=await api('journals?'+new URLSearchParams({company_id:String(props.company),kind:props.kind,page:String(page.value),status:status.value,search:search.value}));if(gen===generation)data.value=result;}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
watch(()=>[props.kind,props.company],()=>{editor.value=null;page.value=1;void load();},{immediate:true});
function create(shortcut=false){quickEntry.value=shortcut;formError.value='';editor.value={request_key:requestKey(),currency:props.book?.currency||'PKR',exchange_rate:'1.000000',posting_date:today,status:'draft',voucher_person:'',reference:'',remarks:'',cash_id:'',offset_id:'',amount:''};}
function hydrate(j:any){const c=j.lines.find((l:any)=>props.accounts.find(a=>a.id===l.account_id)?.account_type==='Cash');const other=j.lines.filter((l:any)=>l!==c);return {...j,cash_id:c?.account_id||'',offset_id:other[0]?.account_id||'',amount:j.currency&&j.currency!==props.book?.currency?String(Number(c?.debit||0)+Number(c?.credit||0)):j.total};}
async function view(row:any){if(row.lines?.length>2){emit('single',row.id);return;}quickEntry.value=false;formError.value='';try{editor.value=hydrate((await api('journals?company_id='+props.company+'&id='+row.id)).journal);savedSignature.value=signature(editor.value);}catch(e){error.value=(e as Error).message;}}
function accountName(id:number){const a=props.accounts.find(a=>a.id===id);return a?a.code+' - '+a.name:'Account unavailable';}
async function run(action:string){if(busy.value)return;if(action==='post'&&signature(editor.value)!==savedSignature.value){formError.value='Save the draft changes before posting.';return;}busy.value=true;formError.value='';try{let result;if(action==='save'){const e=editor.value;result=await api('journals',{company_id:props.company,id:e.id,version:e.version,request_key:e.request_key,currency:e.currency||props.book?.currency,exchange_rate:e.exchange_rate||'1.000000',posting_date:e.posting_date,kind:props.kind,voucher_person:e.voucher_person,reference:e.reference,remarks:e.remarks,lines:[{account_id:e.cash_id,debit:receipt.value?e.amount:'0.00',credit:receipt.value?'0.00':e.amount},{account_id:e.offset_id,debit:receipt.value?'0.00':e.amount,credit:receipt.value?e.amount:'0.00'}]});}else if(action==='post')result=await api('journals/'+editor.value.id+'/post',{company_id:props.company,version:editor.value.version});else result=await api('journals/'+editor.value.id+'/reverse',{company_id:props.company,version:editor.value.version,posting_date:reverseDate.value,reason:reason.value});confirm.value='';if(action==='reverse')editor.value=hydrate((await api('journals?company_id='+props.company+'&id='+editor.value.id)).journal);else editor.value=hydrate(result.journal);savedSignature.value=signature(editor.value);emit('notice',result.message);await load();emit('changed');}catch(e){formError.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section :class="{'ac-document-open':!!editor}"><div class="ac-section-heading"><div><h2>{{title}}</h2><p class="muted">{{receipt?'Record money received into cash.':'Record money paid out of cash.'}}</p></div><div v-if="can(group+'.create')" class="ac-voucher-actions"><button type="button" class="button" @click="create(true)">{{receipt?'Income received':'Expense paid'}}</button><button type="button" class="button primary" @click="create()">+ Create {{receipt?'receipt':'payment'}} voucher</button></div></div>
<p class="ac-help">For customer or supplier invoice settlements, record payment from the original invoice. This avoids duplicate transactions and keeps outstanding balances correct.</p><p v-if="error" class="notice admin-error" role="alert">{{error}}</p>
<form class="ac-filters" @submit.prevent="page=1;load()"><label class="ac-search">Search vouchers<input v-model="search" placeholder="Voucher number, reference or description" type="search"></label><label>Status<AccountingSelect><select v-model="status"><option value="">All statuses</option><option value="draft">Non-posted</option><option value="posted">Posted</option><option value="reversed">Reversed</option></select></AccountingSelect></label><button class="button" :disabled="loading">Apply filters</button></form>
<p v-if="loading" role="status">Loading vouchers...</p><div v-else-if="data" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Voucher</th><th>Date</th><th>{{receipt?'Received from':'Paid to'}}</th><th>Description</th><th>Status</th><th class="numeric">Amount</th><th></th></tr></thead><tbody><tr v-for="row in data.data" :key="row.id"><td><strong>{{row.number}}</strong></td><td>{{row.posting_date}}</td><td>{{row.voucher_person}}</td><td>{{row.remarks||'—'}}</td><td><span class="ac-badge" :class="row.status==='posted'?'active':'inactive'">{{row.status==='draft'?'Non-posted':row.status}}</span></td><td class="numeric">{{money(row.total)}}</td><td><button class="button" @click="view(row)">{{row.status==='draft'&&canManage?'Edit draft':'View voucher'}}</button></td></tr><tr v-if="!data.data.length"><td colspan="7" class="ac-empty-small">No vouchers found.</td></tr></tbody></table></div><div v-if="data" class="ac-pagination"><span>Page {{page}} of {{data.last_page}} · {{data.total}} vouchers</span><button class="button" :disabled="page<=1||loading" @click="page--;load()">Previous</button><button class="button" :disabled="page>=data.last_page||loading" @click="page++;load()">Next</button></div>
<AccountingDocument v-if="editor" :title="editor.number||(receipt?'Create cash receipt voucher':'Create cash payment voucher')" :busy="busy" @close="editor=null"><p v-if="formError" role="alert" class="notice admin-error">{{formError}}</p><div v-if="!book" class="ac-help">Set up company books before saving a voucher. <button type="button" class="button" @click="emit('setup')">Open Company books</button></div><p class="ac-help">{{draft?'Draft — no ledger effect until posted.':'Posted vouchers cannot be edited. Use a reversal for corrections.'}}</p>
<p v-if="quickEntry" class="ac-help">{{receipt?'Income received: choose an Income account to credit.':'Expense paid: choose an Expense account to debit.'}} The Cash side is recorded automatically in this voucher.</p><p v-if="!receipt&&draft" class="ac-help">Payments cannot exceed this Cash account's posted balance on the voucher date. The balance is checked again when posting; drafts do not reserve funds.</p><form @submit.prevent="run('save')"><fieldset class="ac-journal-fields" :disabled="busy||!book||!mayEdit||!draft"><AccountingCurrencyFields :model="editor" :company="company" :base="book?.currency||'PKR'" :date="editor.posting_date"/><div class="ac-form-grid"><label>Voucher date<input v-model="editor.posting_date" type="date" :min="book?.start_date" :max="today" required></label><label>{{receipt?'Received from':'Paid to'}}<input v-model="editor.voucher_person" required maxlength="150" placeholder="Person or organisation"></label><label>Cash account<AccountingSelect><select aria-label="Cash account" v-model.number="editor.cash_id" required><option value="" disabled>Select cash account</option><option v-if="editor.cash_id&&!cash.some(a=>a.id===editor.cash_id)" :value="editor.cash_id">{{accountName(editor.cash_id)}}</option><option v-for="a in cash" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label><label>{{quickEntry?(receipt?'Income account':'Expense account'):(receipt?'Credit account':'Debit account')}}<AccountingSelect><select :aria-label="quickEntry?(receipt?'Income account':'Expense account'):(receipt?'Credit account':'Debit account')" v-model.number="editor.offset_id" required><option value="" disabled>Select account</option><option v-if="editor.offset_id&&!offsets.some(a=>a.id===editor.offset_id)" :value="editor.offset_id">{{accountName(editor.offset_id)}}</option><option v-for="a in offsets" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label><label>Amount ({{book?.currency||'PKR'}})<input aria-label="Voucher amount" v-model="editor.amount" inputmode="decimal" pattern="[0-9]{1,10}(\.[0-9]{1,2})?" required placeholder="0.00"></label><label>Reference<input v-model="editor.reference" maxlength="150"></label><label>Description (optional)<textarea v-model="editor.remarks" maxlength="2000" rows="2"></textarea></label></div></fieldset>
<div class="ac-journal-totals"><span>Debit <strong>{{money(editor.amount)}}</strong></span><span>Credit <strong>{{money(editor.amount)}}</strong></span></div><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="editor=null">Back</button><button v-if="draft&&mayEdit" class="button primary" :disabled="busy||!book"><span v-if="busy" class="ac-spinner"></span>{{busy?'Saving...':'Save draft'}}</button><button v-if="draft&&editor.id&&can(group+'.post')&&!requiresApproval&&!pending" type="button" class="button" :disabled="busy" @click="review">Review posting</button><a v-if="editor.id&&can(group+'.print')" class="button" :href="'/accounting/vouchers/'+editor.id+'/print?company_id='+company" target="_blank" rel="noopener">Print voucher</a><button v-if="editor.status==='posted'&&can(group+'.reverse')" type="button" class="button ac-danger" @click="confirm='reverse';reason='';reverseDate=today">Reverse voucher</button></div></form>
<AccountingApprovalPanel v-if="editor.id&&(requiresApproval||editor.approval)&&(editor.status==='draft'||editor.approval)&&can('workflow.view')" :company="company" type="journal" :document-id="editor.id" :version="editor.version" :csrf="csrf" :unsaved="signature(editor)!==savedSignature" @notice="emit('notice',$event)" @changed="view(editor)"/></AccountingDocument>
<AdminDialog v-if="confirm" :title="confirm==='post'?'Post saved cash voucher':'Reverse cash voucher'" :busy="busy" @close="confirm=''"><p v-if="formError" role="alert" class="notice admin-error">{{formError}}</p><form @submit.prevent="run(confirm)"><template v-if="confirm==='post'"><p>Post the last saved version of <strong>{{editor.number}}</strong> to the ledger? Unsaved form changes are not included.</p><p>{{accountName(editor.cash_id)}} · {{book?.currency}} {{money(editor.total)}}</p></template><template v-else><p>The original voucher remains in history and an opposite journal entry offsets it.</p><label>Reversal date<input v-model="reverseDate" type="date" required :min="editor.posting_date" :max="today"></label><label>Reason<textarea v-model="reason" minlength="5" maxlength="2000" required></textarea></label></template><div class="ac-form-actions"><button class="button" type="button" :disabled="busy" @click="confirm=''">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Processing...':confirm==='post'?'Confirm posting':'Confirm reversal'}}</button></div></form></AdminDialog></section></template>
